from wrapping import wrap

def test_width_less_than_one():
    with pytest.raises(ValueError):
        wrap("hello", 0)
    with pytest.raises(ValueError):
        wrap("hello", -5)

def test_empty_or_whitespace():
    assert wrap("", 5) == ""
    assert wrap("   \t   \n   ", 5) == ""

def test_long_word_split():
    assert wrap("abcdefghij", 4) == "abcd\nefgh\nij"

def test_spaces_tabs_collapse_and_trim():
    assert wrap("  hello\t\tworld   ", 20) == "hello world"

def test_paragraphs_and_newlines():
    assert wrap("one two\nthree\n\n\n  four  ", 20) == "one two three\n\nfour"

def test_breaks_at_whitespace_no_line_longer_than_width():
    text = "the quick brown fox jumps over the lazy dog"
    for w in range(1, 15):
        wrapped = wrap(text, w)
        for line in wrapped.splitlines():
            assert len(line) <= w
            assert not line.startswith(" ")
            assert not line.endswith(" ")
